    for c in range(9, 12):
        grid_adj_fill[r][c] = 5

# Then flood fill adjacent 0s with 5s
from collections import deque

queue = deque()
visited = set()
for r in range(7, 10):
    for c in range(9, 12):
        if grid_adj_fill[r][c] == 5:
            visited.add((r, c))
            queue.append((r, c))

while queue:
    r, c = queue.popleft()
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < 13 and 0 <= nc < 13 and (nr, nc) not in visited:
            if grid_adj_fill[nr][nc] == 0:
                grid_adj_fill[nr][nc] = 5
                visited.add((nr, nc))
                queue.append((nr, nc))

